1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	
50	const BASE_PREMIUMS = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	} as const satisfies Record<string, number>;
58	
59	type InsurableItemType = keyof typeof BASE_PREMIUMS;
60	
61	const basePremiumOf = (item: Item): number =>
62	  BASE_PREMIUMS[item.type as InsurableItemType];
63	
64	/** Premiums are rounded up — in MHPCO's favour. */
65	const roundPremium = (amount: number): number => Math.ceil(amount);
66	
67	const COMPONENT_BLOCK_SIZE = 3;
68	const COMPONENT_BLOCK_PREMIUM = 60;
69	
70	/** Items of a single type, kept together so the block rule can be applied. */
71	type SameTypeGroup = Item[];
72	
73	const groupByType = (items: Item[]): SameTypeGroup[] => {
74	  const groups = new Map<string, SameTypeGroup>();
75	  for (const item of items) {
76	    const group = groups.get(item.type) ?? [];
77	    group.push(item);
78	    groups.set(item.type, group);
79	  }
80	  return [...groups.values()];
81	};
82	
83	const sumBasePremiums = (group: SameTypeGroup): number =>
84	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
85	
86	/**
87	 * Exactly three alike items form a building block priced at a flat premium;
88	 * any other count is priced per item.
89	 */
90	const blockAwareBasePremium = (group: SameTypeGroup): number =>
91	  group.length === COMPONENT_BLOCK_SIZE
92	    ? COMPONENT_BLOCK_PREMIUM
93	    : sumBasePremiums(group);
94	
95	const policyBasePremiumFor = (items: Item[]): number =>
96	  groupByType(items).reduce(
97	    (sum, group) => sum + blockAwareBasePremium(group),
98	    0,
99	  );
100	
101	const HIGH_ENCHANTMENT_LEVEL = 5;
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
106	
107	/**
108	 * An item-specific surcharge: when the item triggers the clause, it is charged
109	 * a rate of that item's own base premium — never of the whole policy's.
110	 */
111	interface ItemSurcharge {
112	  appliesTo: (item: Item) => boolean;
113	  rate: number;
114	}
115	
116	const ITEM_SURCHARGES: ItemSurcharge[] = [
117	  { appliesTo: isCursed, rate: 0.5 },
118	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
119	];
120	
121	/** Every clause the item triggers stacks, each on that item's base premium. */
122	const surchargeRateFor = (item: Item): number =>
123	  ITEM_SURCHARGES.reduce(
124	    (rate, surcharge) =>
125	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
126	    0,
127	  );
128	
129	const itemSurchargesFor = (items: Item[]): number =>
130	  items.reduce(
131	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
132	    0,
133	  );
134	
135	/** Every quote is an initial assessment, so this surcharge always applies. */
136	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
137	const LOYALTY_DISCOUNT_RATE = -0.2;
138	const LOYALTY_YEARS = 2;
139	
140	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
141	
142	/** What the MHPCO knows about the customer when pricing a particular quote. */
143	interface QuoteContext {
144	  customer: Customer;
145	  previousContracts: number;
146	}
147	
148	const isLoyal = ({ customer }: QuoteContext): boolean =>
149	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
150	const isFollowUpContract = ({ previousContracts }: QuoteContext): boolean =>
151	  previousContracts > 0;
152	
153	/**
154	 * A policy-wide modifier: when the customer triggers the clause, the whole
155	 * policy's base premium is adjusted by that rate — never a single item's.
156	 * A negative rate is a discount.
157	 */
158	interface PolicyModifier {
159	  appliesTo: (context: QuoteContext) => boolean;
160	  rate: number;
161	}
162	
163	/** Conditional clauses, on top of the surcharge every quote already carries. */
164	const POLICY_MODIFIERS: PolicyModifier[] = [
165	  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
166	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_DISCOUNT_RATE },
167	];
168	
169	/** Every clause the customer triggers stacks on the policy base premium. */
170	const policyModifierRateFor = (context: QuoteContext): number =>
171	  POLICY_MODIFIERS.reduce(
172	    (rate, modifier) =>
173	      modifier.appliesTo(context) ? rate + modifier.rate : rate,
174	    FIRST_INSURANCE_SURCHARGE_RATE,
175	  );
176	
177	const quotePremium = (items: Item[], context: QuoteContext): number => {
178	  const policyBasePremium = policyBasePremiumFor(items);
179	  return roundPremium(
180	    policyBasePremium +
181	      policyBasePremium * policyModifierRateFor(context) +
182	      itemSurchargesFor(items) +
183	      PROCESSING_FEE,
184	  );
185	};
186	
187	const INSURANCE_VALUES = {
188	  sword: 1000,
189	  amulet: 600,
190	  staff: 800,
191	  potion: 400,
192	  rune: 250,
193	  moonstone: 250,
194	} as const satisfies Record<InsurableItemType, number>;
195	
196	const insuranceValueOf = (item: Item): number =>
197	  INSURANCE_VALUES[item.type as InsurableItemType];
198	
199	const DEDUCTIBLE = 100;
200	const CAP_MULTIPLIER = 2;
201	
202	/** Payouts are rounded down — in MHPCO's favour. */
203	const roundPayout = (amount: number): number => Math.floor(amount);
204	
205	/** A policy created by a quote step, tracked so later claims can draw on it. */
206	interface Policy {
207	  items: Item[];
208	  remainingCap: number;
209	}
210	
211	const openPolicy = (items: Item[]): Policy => ({
212	  items,
213	  remainingCap:
214	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + insuranceValueOf(item), 0),
215	});
216	
217	const FULL_REIMBURSEMENT_RATE = 1;
218	
219	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
220	const REDUCED_REIMBURSEMENT_RATE = 0.5;
221	
222	/** Damage to a very highly enchanted item is only half reimbursed. */
223	const reimbursementRateFor = (item: Item): number =>
224	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL
225	    ? REDUCED_REIMBURSEMENT_RATE
226	    : FULL_REIMBURSEMENT_RATE;
227	
228	/** The deductible can absorb a small damage entirely, but never turns it into a debt. */
229	const afterDeductible = (amount: number): number =>
230	  Math.max(0, amount - DEDUCTIBLE);
231	
232	const payoutForDamage = (damage: Damage, item: Item): number =>
233	  afterDeductible(damage.amount * reimbursementRateFor(item));
234	
235	/**
236	 * Settling draws the payout from the policy's cap, so it yields the policy as
237	 * it stands afterwards rather than modifying the one passed in — the caller
238	 * decides whether to keep the drawn-down policy.
239	 */
240	interface Settlement {
241	  result: StepResult;
242	  policy: Policy;
243	}
244	
245	/**
246	 * Each damage entry is settled against a distinct insured item, so claiming
247	 * for more items of a type than the policy covers is rejected outright.
248	 */
249	const damagedItems = (policy: Policy, damages: Damage[]): Item[] => {
250	  const unclaimed = [...policy.items];
251	  return damages.map((damage) => {
252	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
253	    if (index === -1) {
254	      throw new Error(`${damage.itemType} is not insured by this policy`);
255	    }
256	    return unclaimed.splice(index, 1)[0];
257	  });
258	};
259	
260	const settleClaim = (policy: Policy, incident: Incident): Settlement => {
261	  const items = damagedItems(policy, incident.damages);
262	  const claimedPayout = incident.damages.reduce(
263	    (sum, damage, index) => sum + payoutForDamage(damage, items[index]),
264	    0,
265	  );
266	  const payout = roundPayout(Math.min(claimedPayout, policy.remainingCap));
267	  const remainingCap = policy.remainingCap - payout;
268	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
269	};
270	
271	export const runScenario = (scenario: Scenario): ScenarioResult => {
272	  let previousContracts = 0;
273	  const policies = new Map<number, Policy>();
274	
275	  const results = scenario.steps.map((step, index) => {
276	    if (step.op === "quote") {
277	      const context = { customer: scenario.customer, previousContracts };
278	      previousContracts += 1;
279	      policies.set(index, openPolicy(step.items));
280	      return { premium: quotePremium(step.items, context) };
281	    }
282	
283	    const policy = policies.get(step.policy);
284	    if (policy === undefined) {
285	      throw new Error(`No policy created by step ${step.policy}`);
286	    }
287	    const settlement = settleClaim(policy, step.incident);
288	    policies.set(step.policy, settlement.policy);
289	    return settlement.result;
290	  });
291	
292	  return { results };
293	};
